import { z, ZodSchema } from 'zod';

/**
 * Utility functions for handling AI responses and data parsing.
 */

export const cleanJsonOutput = (text: string): string => {
    // 1. Priority: Look for standard markdown code blocks with json identifier
    const jsonBlockMatch = text.match(/```json\s*([\s\S]*?)\s*```/i);
    if (jsonBlockMatch && jsonBlockMatch[1]) {
        return jsonBlockMatch[1].trim();
    }

    // 2. Secondary: Look for generic code blocks if the model forgot "json"
    const genericBlockMatch = text.match(/```\s*([\s\S]*?)\s*```/i);
    if (genericBlockMatch && genericBlockMatch[1]) {
         const content = genericBlockMatch[1].trim();
         if (content.startsWith('{') && content.endsWith('}')) {
             return content;
         }
    }

    // 3. Fallback: Robust search for valid JSON object.
    let startIndex = text.indexOf('{');
    const lastIndex = text.lastIndexOf('}');

    while (startIndex !== -1 && lastIndex > startIndex) {
        const candidate = text.substring(startIndex, lastIndex + 1);
        try {
            JSON.parse(candidate);
            return candidate; 
        } catch (e) {
            startIndex = text.indexOf('{', startIndex + 1);
        }
    }

    // Last Ditch: Just return the text.
    return text.trim();
};

export const parseJsonSafe = <T>(content: string): T | null => {
    try {
        const cleaned = cleanJsonOutput(content);
        if (!cleaned.startsWith('{')) return null;
        return JSON.parse(cleaned) as T;
    } catch (e) {
        return null;
    }
};

/**
 * Validates parsed JSON against a Zod schema.
 * Returns null if validation fails, logging the error.
 */
export const parseAndValidate = <T>(content: string, schema: ZodSchema<T>): T | null => {
    try {
        const cleaned = cleanJsonOutput(content);
        let parsed;
        try {
            parsed = JSON.parse(cleaned);
        } catch {
            return null; // Invalid JSON syntax
        }

        const result = schema.safeParse(parsed);

        if (result.success) {
            return result.data;
        } else {
            console.warn("Zod Validation Failed:", result.error);
            return null;
        }
    } catch (e) {
        console.error("Parse Error:", e);
        return null;
    }
};

export const isJsonBriefing = (content: string): boolean => {
    // Quick heuristics, but consumers should use Zod for use
    return content.includes('briefingTitle') && content.includes('sections');
};

export const isImageAnalysis = (content: string): boolean => {
     return content.includes('"reportType": "medical-image"') || content.includes('"reportType":"medical-image"');
};

export const isLabReport = (content: string): boolean => {
    return content.includes('"reportType": "lab-report"') || content.includes('"reportType":"lab-report"');
};

export const isInteractionMatrix = (content: string): boolean => {
    return content.includes('"reportType": "interaction-check"') || content.includes('"reportType":"interaction-check"');
};

export const getFriendlyErrorMessage = (error: unknown): string => {
    let errorMessage = 'An unknown error occurred.';
    if (error instanceof Error) {
        try {
            const errorObj = JSON.parse(error.message);
            if (errorObj.error && errorObj.error.message) {
                const message = errorObj.error.message.toLowerCase();
                if (message.includes('overloaded') || message.includes('too many requests') || errorObj.error.code === 503 || errorObj.error.code === 500) {
                    return 'The service is currently experiencing high demand. Please wait a moment and try again.';
                }
                 if (message.includes('api key not valid')) {
                    return 'The API key is not valid. Please check your configuration.';
                }
                return errorObj.error.message; 
            } else {
                return error.message; 
            }
        } catch (parseError) {
            if (error.message.toLowerCase().includes('permission denied')) {
                return 'Microphone access was denied. Please allow microphone permission in your browser settings.';
            }
            return error.message;
        }
    } else if (typeof error === 'string') {
        return error;
    }
    return errorMessage;
};

import React, { useRef, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { ChatMode as ChatModeEnum, UploadedFile, ChatMessage, GroundingSource } from '../../../types';
import { generateResponseStream } from '../../../services/geminiService';
import { exportBriefingToPdf } from '../../../services/exportService';
import { cleanJsonOutput, isJsonBriefing, getFriendlyErrorMessage, isLabReport, parseAndValidate } from '../../../utils';
import { FILE_ANALYSIS_PROMPT, BRIEFING_TRIGGERS, SHIFT_BRIEFING_PROMPT, HELP_COMMAND_RESPONSE, DRUG_ANALYSIS_PROMPT } from '../../../constants';
import { usePatientStore } from '../../patient-management/usePatientStore';
import { useChatStore } from '../stores/useChatStore';
import { useClinicalStore } from '../../clinical-analysis/stores/useClinicalStore';
import { useEntityExtractor } from '../../../hooks/useEntityExtractor';
import { FHIRObservation } from '../../fhir/types';
import { evaluateClinicalSafety } from '../../cdss/rulesEngine';
import { PatientMetadata } from '../../patient-management/types';
import { UIAction } from '../../ui/UIContext';
import { LabReportSchema, BriefingSchema } from '../schemas';

interface UseChatOrchestratorProps {
    messages: ChatMessage[];
    activePatientId: string;
    activePatient: PatientMetadata;
    chatMode: ChatModeEnum;
    uiDispatch: React.Dispatch<UIAction>;
    uploadedFile: UploadedFile | null;
    setUploadedFile: (file: UploadedFile | null) => void;
    isLive: boolean;
    stopSession: () => void;
    userLocation?: { latitude: number, longitude: number };
    clearFile: () => void;
}

export const useChatOrchestrator = ({
    messages,
    activePatientId,
    activePatient,
    chatMode,
    uiDispatch,
    uploadedFile,
    setUploadedFile,
    isLive,
    stopSession,
    userLocation,
    clearFile
}: UseChatOrchestratorProps) => {
    // Access actions from all 3 stores
    const patientActions = usePatientStore(state => state.actions);
    const chatActions = useChatStore(state => state.actions);
    const clinicalActions = useClinicalStore(state => state.actions);

    const abortControllerRef = useRef<AbortController | null>(null);
    const { triggerExtraction } = useEntityExtractor();

    const handleStop = useCallback(() => {
        if (abortControllerRef.current) abortControllerRef.current.abort();
        uiDispatch({ type: 'SET_LOADING', payload: false });
    }, [uiDispatch]);

    const handleClearChat = useCallback(() => {
        chatActions.resetChat(activePatientId);
        clearFile();
    }, [chatActions, activePatientId, clearFile]);

    const handleSend = useCallback(async (userPrompt: string) => {
        const trimmedPrompt = userPrompt.trim();
        if (!trimmedPrompt && !uploadedFile) return;

        if (isLive) {
            stopSession();
            uiDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Standard });
        }

        // Update last active
        patientActions.touchPatient(activePatientId);

        // --- Export Command ---
        if (trimmedPrompt.toLowerCase() === '/export') {
            const history = messages.filter(m => !isJsonBriefing(m.content));
            if (history.length === 0) {
                 chatActions.addMessage(activePatientId, { role: 'model', content: '⚠️ **Cannot Export:** No history available.' });
                 return;
            }

            chatActions.addMessage(activePatientId, { role: 'model', content: '📥 Generating briefing for PDF export...' });
            uiDispatch({ type: 'SET_LOADING', payload: true });

            abortControllerRef.current = new AbortController();
            try {
                const modeForRequest = ChatModeEnum.Standard;
                const stream = generateResponseStream(SHIFT_BRIEFING_PROMPT(), history, modeForRequest, { responseType: 'json' });
                let fullResponseText = '';
                for await (const chunk of stream) {
                    if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");
                    fullResponseText += chunk.text;
                }

                if (fullResponseText.includes("NO DATA")) throw new Error("Insufficient clinical data found.");

                // Use Zod validation for PDF export
                const parsedBriefing = parseAndValidate(fullResponseText, BriefingSchema);
                if (!parsedBriefing) throw new Error("Invalid briefing format generated by AI.");

                if (parsedBriefing.briefingTitle.includes("NO DATA")) throw new Error("Insufficient clinical data.");

                await exportBriefingToPdf(parsedBriefing);
                chatActions.updateLastMessageContent(activePatientId, '✅ Shift briefing PDF downloaded.');
            } catch (e) {
                if (e.message === "Aborted") {
                     chatActions.updateLastMessageContent(activePatientId, '🛑 Export cancelled.');
                } else {
                    const friendlyError = getFriendlyErrorMessage(e);
                    chatActions.updateLastMessageContent(activePatientId, `Sorry, PDF generation failed.\n\n**Reason:** ${friendlyError}`);
                }
            } finally {
                uiDispatch({ type: 'SET_LOADING', payload: false });
                abortControllerRef.current = null;
            }
            return;
        }

        // --- Help Command ---
        if (trimmedPrompt.toLowerCase() === '/help') {
             chatActions.addMessage(activePatientId, { role: 'user', content: '/help' });
             chatActions.addMessage(activePatientId, { role: 'model', content: HELP_COMMAND_RESPONSE });
             return;
        }

        // --- Standard Message & File Handling ---
        let finalApiPrompt = trimmedPrompt;
        let historyContent = trimmedPrompt;

        let fileForApi: UploadedFile | undefined = uploadedFile || undefined;

        let displayOverride = undefined;
        let modeForRequest: ChatModeEnum = chatMode === ChatModeEnum.Live ? ChatModeEnum.Standard : chatMode;
        let responseType: 'json' | 'text' = 'text';

        const isBriefingCommand = BRIEFING_TRIGGERS.some(trigger => trimmedPrompt.toLowerCase().includes(trigger)) || trimmedPrompt.toLowerCase() === '/brief';
        const isDrugCommand = trimmedPrompt.toLowerCase().startsWith('/drugs');

        if (uploadedFile) {
             if (activePatientId) {
                 triggerExtraction(uploadedFile, activePatientId);
             }

             try {
                let analysisPrompt: string;
                if (uploadedFile.type === 'application/pdf') {
                    const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this medical document.`;
                    analysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name) + `\n\n${promptBase}`;
                } else if (uploadedFile.type === 'text/plain' || uploadedFile.file.name.endsWith('.txt') || uploadedFile.file.name.endsWith('.md')) {
                     const textContent = await uploadedFile.file.text();
                     const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this document.`;
                     const fullEmbeddedContent = `*** BEGIN FILE CONTENT: ${uploadedFile.file.name} ***\n${textContent}\n*** END FILE CONTENT ***\n\n${promptBase}`;
                     analysisPrompt = fullEmbeddedContent;
                     historyContent = fullEmbeddedContent;
                     displayOverride = `📄 **Uploaded ${uploadedFile.file.name}**\n\n${trimmedPrompt || "Requested analysis."}`;
                     fileForApi = undefined; 
                } else {
                    const baseAnalysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name);
                    if (!trimmedPrompt) {
                        analysisPrompt = baseAnalysisPrompt;
                        displayOverride = `Analyzing file: ${uploadedFile.file.name}`; 
                    } else {
                        analysisPrompt = `${baseAnalysisPrompt}\n\n---\n**ADDITIONAL INSTRUCTION:**\nThe user has asked: "${trimmedPrompt}".\n1. You MUST still output VALID JSON.\n2. Answer the user's question within the "visualObservations" or "note" fields.`;
                    }
                }

                finalApiPrompt = analysisPrompt;
                if (isBriefingCommand) {
                    finalApiPrompt = `${finalApiPrompt}\n\nIMPORTANT: After analyzing, ${SHIFT_BRIEFING_PROMPT()}`;
                    modeForRequest = ChatModeEnum.Standard;
                    responseType = 'json';
                    if (!displayOverride) historyContent = trimmedPrompt || "/brief (with file)";
                }
             } catch (error) {
                 chatActions.addMessage(activePatientId, { role: 'model', content: `Error: ${getFriendlyErrorMessage(error)}` });
                 uiDispatch({ type: 'SET_ERROR', payload: getFriendlyErrorMessage(error) });
                 return;
             }
        } else if (isBriefingCommand) {
            finalApiPrompt = SHIFT_BRIEFING_PROMPT();
            historyContent = "/brief"; 
            modeForRequest = ChatModeEnum.Standard;
            responseType = 'json';
        } else if (isDrugCommand) {
            finalApiPrompt = DRUG_ANALYSIS_PROMPT(trimmedPrompt);
            modeForRequest = ChatModeEnum.Standard; 
            responseType = 'json';
        }

        if (trimmedPrompt.toLowerCase().startsWith('/patient')) modeForRequest = ChatModeEnum.Standard;

        const userMessage: ChatMessage = { role: 'user', content: historyContent };
        if (displayOverride) userMessage.displayContent = displayOverride;

        if (uploadedFile && fileForApi) { 
            userMessage.filePreview = { 
                name: uploadedFile.file.name, 
                type: uploadedFile.type, 
                url: uploadedFile.url,
                storageId: uploadedFile.storageId 
            };
        }

        chatActions.addMessage(activePatientId, userMessage);
        chatActions.addResponsePlaceholder(activePatientId);
        uiDispatch({ type: 'SET_LOADING', payload: true });
        uiDispatch({ type: 'SET_ERROR', payload: null });
        setUploadedFile(null);

        abortControllerRef.current = new AbortController();
        let fullResponseBuffer = '';

        try {
            const history = [...messages];
            const stream = generateResponseStream(finalApiPrompt, history, modeForRequest, { file: fileForApi, responseType, location: userLocation });

            for await (const chunk of stream) {
                if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");

                const textChunk = chunk.text || '';
                fullResponseBuffer += textChunk;

                const groundingMetadata = chunk.candidates?.[0]?.groundingMetadata;
                let sources: GroundingSource[] | undefined = undefined;

                if (groundingMetadata && groundingMetadata.groundingChunks) {
                    sources = groundingMetadata.groundingChunks.map(chunk => {
                        if (chunk.web) return { web: chunk.web };
                        if ((chunk as any).maps) return { maps: (chunk as any).maps };
                        return undefined;
                    }).filter(Boolean) as GroundingSource[];
                }

                chatActions.appendToLastMessage(activePatientId, textChunk, sources);
            }
        } catch (e) {
             if (e.message === "Aborted") {
                 chatActions.appendToLastMessage(activePatientId, " [Stopped]", undefined);
            } else {
                const errorMsg = `Sorry, I encountered an error.\n\n**Details:** ${getFriendlyErrorMessage(e)}`;
                chatActions.updateLastMessageContent(activePatientId, errorMsg);
            }
        } finally {
            uiDispatch({ type: 'SET_LOADING', payload: false });

            // --- FHIR AUTO-INGESTION PROTOCOL WITH ZOD ---
            // Only ingest if it passes the strict schema for a Lab Report
            if (activePatientId && isLabReport(fullResponseBuffer)) {
                // Safe parsing with Zod
                const report = parseAndValidate(fullResponseBuffer, LabReportSchema);

                if (report && report.labs) {
                    const newObs: FHIRObservation[] = report.labs.map((lab: any) => {
                         const val = parseFloat(lab.value.replace(/[^0-9.-]/g, ''));
                         const rangeMatch = lab.refRange.match(/([\d.]+)\s*-\s*([\d.]+)/);

                         if (isNaN(val)) return null;

                         const obs: FHIRObservation = {
                             resourceType: 'Observation',
                             id: uuidv4(),
                             status: 'final',
                             code: { 
                                 text: lab.testName 
                             },
                             subject: { reference: `Patient/${activePatientId}` },
                             valueQuantity: { 
                                 value: val, 
                                 unit: lab.units,
                                 system: 'http://unitsofmeasure.org'
                             },
                             effectiveDateTime: report.date && report.date !== 'Not Visible' ? new Date(report.date).toISOString() : new Date().toISOString(),
                             issued: new Date().toISOString()
                         };

                         if (rangeMatch) {
                             obs.referenceRange = [{
                                 low: { value: parseFloat(rangeMatch[1]), unit: lab.units, system: 'http://unitsofmeasure.org' },
                                 high: { value: parseFloat(rangeMatch[2]), unit: lab.units, system: 'http://unitsofmeasure.org' },
                                 text: lab.refRange
                             }];
                         }

                         if (lab.flag && lab.flag !== 'Normal') {
                             obs.interpretation = [{ text: lab.flag }];
                         }

                         return obs;
                    }).filter(Boolean);

                    if (newObs.length > 0) {
                        clinicalActions.ingestObservations(activePatientId, newObs);

                        const existingObs = useClinicalStore.getState().data[activePatientId]?.observations || [];
                        const combinedObs = [...existingObs, ...newObs];

                        evaluateClinicalSafety(combinedObs).then(alerts => {
                            if (alerts.length > 0) {
                                clinicalActions.updateAlerts(activePatientId, alerts);
                            }
                        });
                    }
                } else {
                    console.warn("Lab report detected but failed validation.");
                }
            }

            abortControllerRef.current = null;
        }
    }, [messages, activePatientId, chatMode, uploadedFile, isLive, stopSession, userLocation, patientActions, chatActions, clinicalActions, uiDispatch, setUploadedFile, triggerExtraction]);

    return {
        handleSend,
        handleStop,
        handleClearChat,
        handleExportChat: useCallback(() => handleSend('/export'), [handleSend])
    };
};

import { GoogleGenAI } from "@google/genai";
import { UploadedFile } from '../../types';
import { ENTITY_EXTRACTION_PROMPT } from '../../constants';
import { cleanJsonOutput, parseAndValidate } from '../../utils';
import { PatientEntityData } from '../patient-management/types';
import { EntityExtractionSchema } from '../chat/schemas';

const MODEL = 'gemini-3-flash-preview'; 

export const extractEntitiesFromUpload = async (file: UploadedFile): Promise<Partial<PatientEntityData>> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const contents = [
            {
                role: 'user',
                parts: [
                    {
                        inlineData: {
                            mimeType: file.type,
                            data: file.base64
                        }
                    },
                    { text: ENTITY_EXTRACTION_PROMPT }
                ]
            }
        ];

        const response = await ai.models.generateContent({
            model: MODEL,
            contents: contents,
            config: {
                responseMimeType: 'application/json'
            }
        });

        const text = response.text;
        if (!text) return {};

        // Validated parsing
        const parsed = parseAndValidate(text, EntityExtractionSchema);
        if (!parsed) return {};

        const result: Partial<PatientEntityData> = {};

        if (parsed.allergies && parsed.allergies.length > 0) {
            result.allergies = parsed.allergies;
        }

        if (parsed.codeStatus && parsed.codeStatus.trim()) {
            result.codeStatus = parsed.codeStatus.trim();
        }

        if (parsed.diagnosis && parsed.diagnosis.length > 0) {
            result.diagnosis = parsed.diagnosis;
        }

        return result;

    } catch (e) {
        console.warn("Entity Extraction Failed:", e);
        return {};
    }
};

import { GoogleGenAI } from "@google/genai";
import { parseAndValidate } from '../../utils';
import { ParsedMedication } from './types';
import { MedicationListSchema } from '../chat/schemas';

const MODEL = 'gemini-3-flash-preview'; 

const EXTRACTION_PROMPT = `
You are a Clinical Entity Extractor.
Extract all medications and their specific dosages from the provided text.

**RULES:**
1. Return ONLY valid JSON.
2. Normalize the drug name to its generic name if possible (e.g., "Tylenol" -> "Acetaminophen").
3. Extract numerical amount and unit separately.
4. If no dosage is specified, set amount to 0.

**OUTPUT SCHEMA:**
\`\`\`json
[
  { 
    "drugName": "string", 
    "amount": number, 
    "unit": "string" (e.g., "mg", "g", "mcg", "IU"),
    "context": "string" (e.g., "taking", "prescribed", "discontinued")
  }
]
\`\`\`

If no medications are found, return an empty array [].
`;

export const extractMedicationsFromText = async (text: string): Promise<ParsedMedication[]> => {
    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const response = await ai.models.generateContent({
            model: MODEL,
            contents: [
                {
                    role: 'user',
                    parts: [
                        { text: EXTRACTION_PROMPT },
                        { text: `\n\n**TEXT TO ANALYZE:**\n${text}` }
                    ]
                }
            ],
            config: {
                responseMimeType: 'application/json',
                temperature: 0
            }
        });

        const output = response.text;
        if (!output) return [];

        const parsed = parseAndValidate(output, MedicationListSchema);

        if (parsed) {
            return parsed;
        }
        return [];

    } catch (e) {
        console.warn("Safety Extraction Failed:", e);
        return [];
    }
};

import { get, set, del } from 'idb-keyval';
import { StateStorage } from 'zustand/middleware';

// Custom Storage Engine for Zustand that uses IndexedDB (Async)
// This bypasses the 5MB limit of localStorage/sessionStorage
export const indexedDBStorage: StateStorage = {
    getItem: async (name: string): Promise<string | null> => {
        return (await get(name)) || null;
    },
    setItem: async (name: string, value: string): Promise<void> => {
        await set(name, value);
    },
    removeItem: async (name: string): Promise<void> => {
        await del(name);
    },
};

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { ChatMessage, GroundingSource } from '../../../types';
import { indexedDBStorage } from '../../../services/storage';

interface ChatState {
    chats: Record<string, ChatMessage[]>;
}

interface ChatActions {
    actions: {
        initializeChat: (patientId: string) => void;
        deleteChat: (patientId: string) => void;
        resetChat: (patientId: string) => void;

        // Message Operations
        addMessage: (patientId: string, message: ChatMessage) => void;
        addResponsePlaceholder: (patientId: string) => void;
        appendToLastMessage: (patientId: string, chunk: string, sources?: GroundingSource[]) => void;
        updateLastMessageContent: (patientId: string, content: string) => void;
    }
}

export const useChatStore = create<ChatState & ChatActions>()(
    persist(
        (set) => ({
            chats: {},
            actions: {
                initializeChat: (patientId) => set((state) => {
                    if (state.chats[patientId]) return state;
                    return { chats: { ...state.chats, [patientId]: [] } };
                }),
                deleteChat: (patientId) => set((state) => {
                    const newChats = { ...state.chats };
                    delete newChats[patientId];
                    return { chats: newChats };
                }),
                resetChat: (patientId) => set((state) => ({
                    chats: { ...state.chats, [patientId]: [] }
                })),

                addMessage: (patientId, message) => set((state) => ({
                    chats: {
                        ...state.chats,
                        [patientId]: [...(state.chats[patientId] || []), message]
                    }
                })),

                addResponsePlaceholder: (patientId) => set((state) => ({
                    chats: {
                        ...state.chats,
                        [patientId]: [...(state.chats[patientId] || []), { role: 'model', content: '' }]
                    }
                })),

                appendToLastMessage: (patientId, chunk, sources) => set((state) => {
                    const history = [...(state.chats[patientId] || [])];
                    const lastMsg = history[history.length - 1];

                    if (lastMsg && lastMsg.role === 'model') {
                        lastMsg.content += chunk;
                        if (sources) {
                            const existing = lastMsg.sources || [];
                            // Dedup sources
                            const newSources = sources.filter(ns => 
                                !existing.some(es => 
                                    (es.web?.uri && es.web.uri === ns.web?.uri) || 
                                    (es.maps?.uri && es.maps.uri === ns.maps?.uri)
                                )
                            );
                            lastMsg.sources = [...existing, ...newSources];
                        }
                    }

                    return {
                        chats: { ...state.chats, [patientId]: history }
                    };
                }),

                updateLastMessageContent: (patientId, content) => set((state) => {
                    const history = [...(state.chats[patientId] || [])];
                    const lastMsg = history[history.length - 1];
                    if (lastMsg) lastMsg.content = content;

                    return {
                        chats: { ...state.chats, [patientId]: history }
                    };
                })
            }
        }),
        {
            name: 'medibrief-chat-storage',
            storage: createJSONStorage(() => indexedDBStorage),
        }
    )
);

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { FHIRObservation, ClinicalDataStore } from '../../fhir/types';
import { CDSSAlert } from '../../cdss/types';
import { indexedDBStorage } from '../../../services/storage';

interface ClinicalState {
    data: Record<string, ClinicalDataStore>;
    alerts: Record<string, CDSSAlert[]>;
}

interface ClinicalActions {
    actions: {
        initializePatient: (patientId: string) => void;
        deletePatient: (patientId: string) => void;

        ingestObservations: (patientId: string, observations: FHIRObservation[]) => void;
        updateAlerts: (patientId: string, alerts: CDSSAlert[]) => void;
        dismissAlert: (patientId: string, alertId: string) => void;
    }
}

export const useClinicalStore = create<ClinicalState & ClinicalActions>()(
    persist(
        (set) => ({
            data: {},
            alerts: {},
            actions: {
                initializePatient: (patientId) => set((state) => {
                    if (state.data[patientId]) return state;
                    return {
                        data: { ...state.data, [patientId]: { observations: [] } },
                        alerts: { ...state.alerts, [patientId]: [] }
                    };
                }),
                deletePatient: (patientId) => set((state) => {
                    const newData = { ...state.data };
                    const newAlerts = { ...state.alerts };
                    delete newData[patientId];
                    delete newAlerts[patientId];
                    return { data: newData, alerts: newAlerts };
                }),

                ingestObservations: (patientId, observations) => set((state) => {
                    const currentStore = state.data[patientId] || { observations: [] };
                    const existingObs = currentStore.observations;

                    // Deduplication Logic
                    const newObs = observations.filter(obs => 
                        !existingObs.some(ex => 
                            ex.code.text === obs.code.text && 
                            ex.valueQuantity?.value === obs.valueQuantity?.value &&
                            ex.effectiveDateTime === obs.effectiveDateTime
                        )
                    );

                    return {
                        data: {
                            ...state.data,
                            [patientId]: {
                                ...currentStore,
                                observations: [...existingObs, ...newObs]
                            }
                        }
                    };
                }),

                updateAlerts: (patientId, incomingAlerts) => set((state) => {
                    const currentAlerts = state.alerts[patientId] || [];

                    // Dedup alerts by title/timeframe
                    const newAlerts = incomingAlerts.filter(na => 
                        !currentAlerts.some(ca => ca.title === na.title && ca.timestamp > Date.now() - 3600000)
                    );

                    return {
                        alerts: {
                            ...state.alerts,
                            [patientId]: [...currentAlerts, ...newAlerts]
                        }
                    };
                }),

                dismissAlert: (patientId, alertId) => set((state) => {
                    const currentAlerts = state.alerts[patientId] || [];
                    return {
                        alerts: {
                            ...state.alerts,
                            [patientId]: currentAlerts.filter(a => a.id !== alertId && a.ruleId !== alertId)
                        }
                    };
                })
            }
        }),
        {
            name: 'medibrief-clinical-storage',
            storage: createJSONStorage(() => indexedDBStorage),
        }
    )
);

/**
 * PCM Processor for MediBrief Audio Streaming.
 * Processes raw float32 audio data and buffers it into 4096-sample chunks for the main thread.
 * 
 * Note: This file is loaded via AudioWorklet.addModule() to avoid inline script violations.
 */
class PCMProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.bufferSize = 4096;
    this.buffer = new Float32Array(this.bufferSize);
    this.index = 0;
  }

  process(inputs, outputs, parameters) {
    const input = inputs[0];
    if (input && input.length > 0) {
      const channelData = input[0];
      for (let i = 0; i < channelData.length; i++) {
        this.buffer[this.index++] = channelData[i];
        if (this.index >= this.bufferSize) {
          this.port.postMessage(this.buffer);
          this.index = 0;
        }
      }
    }
    return true;
  }
}

registerProcessor('pcm-processor', PCMProcessor);

import { useState, useRef, useCallback, useEffect } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { MODEL_CONFIGS, SYSTEM_INSTRUCTION } from '../constants';
import { ChatMode, ChatMessage } from '../types';

declare global {
  interface Window {
    webkitAudioContext: typeof AudioContext;
  }
}

// Type definition for the object expected by session.sendRealtimeInput
type LiveInputMedia = {
    data: string;
    mimeType: string;
};

const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const createBlob = (data: Float32Array): LiveInputMedia => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    const clamped = Math.max(-1, Math.min(1, data[i]));
    int16[i] = clamped < 0 ? clamped * 0x8000 : clamped * 0x7FFF;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

type LiveSession = Awaited<ReturnType<InstanceType<typeof GoogleGenAI>['live']['connect']>>;

export interface UseLiveSessionReturn {
    isLive: boolean;
    transcript: { userInput: string; modelOutput: string };
    startSession: (history?: ChatMessage[]) => Promise<void>;
    stopSession: () => Promise<void>;
    error: string | null;
}

export const useLiveSession = (onTurnComplete?: (userInput: string, modelOutput: string) => void): UseLiveSessionReturn => {
    const [isLive, setIsLive] = useState(false);
    const [transcript, setTranscript] = useState({ userInput: '', modelOutput: '' });
    const [error, setError] = useState<string | null>(null);

    const accumulatedTranscriptRef = useRef({ userInput: '', modelOutput: '' });
    const liveSessionRef = useRef<LiveSession | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
    const nextStartTimeRef = useRef<number>(0);
    const mediaStreamSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);

    // Processors
    const workletNodeRef = useRef<AudioWorkletNode | null>(null);
    const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
    const workletSupportedRef = useRef<boolean>(false);

    const isStoppingRef = useRef(false);

    const stopSession = useCallback(async () => {
        if (isStoppingRef.current) return;
        isStoppingRef.current = true;

        try {
            // 1. Close the session socket first
            if (liveSessionRef.current) {
                liveSessionRef.current.close();
                liveSessionRef.current = null;
            }

            // 2. Disconnect audio nodes
            workletNodeRef.current?.disconnect();
            scriptProcessorRef.current?.disconnect();
            mediaStreamSourceRef.current?.disconnect();

            workletNodeRef.current = null;
            scriptProcessorRef.current = null;
            mediaStreamSourceRef.current = null;

            // 3. Stop all playing audio
            audioSourcesRef.current.forEach(source => {
                try { source.stop(); } catch(e) {}
            });
            audioSourcesRef.current.clear();

            // 4. Suspend AudioContexts cleanly
            if (inputAudioContextRef.current && inputAudioContextRef.current.state === 'running') {
                try { await inputAudioContextRef.current.suspend(); } catch(e) { console.warn("Input suspend failed", e); }
            }
            if (outputAudioContextRef.current && outputAudioContextRef.current.state === 'running') {
                try { await outputAudioContextRef.current.suspend(); } catch(e) { console.warn("Output suspend failed", e); }
            }

            nextStartTimeRef.current = 0;

            // 5. Finalize transcript
            if ((accumulatedTranscriptRef.current.userInput || accumulatedTranscriptRef.current.modelOutput) && onTurnComplete) {
                onTurnComplete(accumulatedTranscriptRef.current.userInput, accumulatedTranscriptRef.current.modelOutput);
            }

            accumulatedTranscriptRef.current = { userInput: '', modelOutput: '' };
            setTranscript({ userInput: '', modelOutput: '' });

        } catch (e) {
            console.error("Error during session stop:", e);
        } finally {
            setIsLive(false);
            isStoppingRef.current = false;
        }
    }, [onTurnComplete]);

    const startSession = useCallback(async (history: ChatMessage[] = []) => {
        if (isLive || isStoppingRef.current) return;

        setError(null);
        accumulatedTranscriptRef.current = { userInput: '', modelOutput: '' };

        try {
            // SAFETY CHECK: Check if mediaDevices API exists (it doesn't on insecure HTTP)
            if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                throw new Error("Media API not available. Secure context (HTTPS) required.");
            }

            // 1. Initialize Audio Contexts (Singleton Pattern)
            if (!inputAudioContextRef.current || inputAudioContextRef.current.state === 'closed') {
                inputAudioContextRef.current = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 16000 });
            }
            if (!outputAudioContextRef.current || outputAudioContextRef.current.state === 'closed') {
                outputAudioContextRef.current = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 24000 });
            }

            // Resume if suspended
            if (inputAudioContextRef.current.state === 'suspended') await inputAudioContextRef.current.resume();
            if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();

            // 2. Load AudioWorklet Module (CSP Compliant via static file)
            try {
                await inputAudioContextRef.current.audioWorklet.addModule('/workers/pcm-processor.js');
                workletSupportedRef.current = true;
            } catch (e) {
                console.warn("AudioWorklet module load failed, defaulting to ScriptProcessor fallback:", e);
                workletSupportedRef.current = false;
            }

            // 3. Get User Media
            let stream: MediaStream;
            try {
                stream = await navigator.mediaDevices.getUserMedia({ 
                    audio: {
                        echoCancellation: true,
                        noiseSuppression: true,
                        autoGainControl: true,
                    } 
                });
            } catch (mediaError: any) {
                if (mediaError.name === 'NotFoundError' || mediaError.name === 'DevicesNotFoundError') {
                    throw new Error("No microphone found on this device.");
                }
                if (mediaError.name === 'NotAllowedError' || mediaError.name === 'PermissionDeniedError') {
                    throw new Error("Microphone permission denied by user.");
                }
                throw mediaError;
            }

            setIsLive(true);

            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            // 4. Build Context String
            let contextString = "";
            if (history.length > 0) {
                const recentHistory = history.slice(-6).filter(m => m.content).map(m => {
                    const content = m.content.length > 200 ? m.content.substring(0, 200) + "..." : m.content;
                    return `${m.role.toUpperCase()}: ${content}`;
                }).join("\n");
                contextString = `\n\n[CONTEXT: ${recentHistory}]`;
            }

            // 5. Connect to Live API
            const sessionPromise = ai.live.connect({
                model: MODEL_CONFIGS[ChatMode.Live].model,
                config: {
                    ...MODEL_CONFIGS[ChatMode.Live].config,
                    systemInstruction: SYSTEM_INSTRUCTION + contextString
                },
                callbacks: {
                    onopen: async () => {
                        if (!inputAudioContextRef.current) return;
                        mediaStreamSourceRef.current = inputAudioContextRef.current.createMediaStreamSource(stream);

                        if (workletSupportedRef.current) {
                            // PRIMARY: AudioWorklet
                            try {
                                workletNodeRef.current = new AudioWorkletNode(inputAudioContextRef.current, 'pcm-processor');
                                workletNodeRef.current.port.onmessage = (event) => {
                                    const inputData = event.data;
                                    const pcmBlob = createBlob(inputData);
                                    sessionPromise.then((session) => session.sendRealtimeInput({ media: pcmBlob }));
                                };
                                mediaStreamSourceRef.current.connect(workletNodeRef.current);
                                workletNodeRef.current.connect(inputAudioContextRef.current.destination);
                            } catch (e) {
                                console.error("Worklet creation failed:", e);
                                workletSupportedRef.current = false; 
                                fallbackToScriptProcessor(sessionPromise);
                            }
                        } else {
                            // FALLBACK: ScriptProcessor
                            fallbackToScriptProcessor(sessionPromise);
                        }
                    },
                    onmessage: async (message: LiveServerMessage) => {
                        if (message.serverContent?.inputTranscription) {
                            accumulatedTranscriptRef.current.userInput += message.serverContent.inputTranscription.text;
                            setTranscript(prev => ({ ...prev, userInput: accumulatedTranscriptRef.current.userInput }));
                        }
                        if (message.serverContent?.outputTranscription) {
                            accumulatedTranscriptRef.current.modelOutput += message.serverContent.outputTranscription.text;
                            setTranscript(prev => ({ ...prev, modelOutput: accumulatedTranscriptRef.current.modelOutput }));
                        }

                        if (message.toolCall) {
                             for (const fc of message.toolCall.functionCalls) {
                                const result = { result: "Success" };
                                sessionPromise.then((session) => {
                                    if (liveSessionRef.current) {
                                        session.sendToolResponse({
                                            functionResponses: [{ id: fc.id, name: fc.name, response: result }]
                                        });
                                    }
                                });
                            }
                        }

                        const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData && outputAudioContextRef.current) {
                            const outCtx = outputAudioContextRef.current;
                            if (outCtx.state === 'suspended') await outCtx.resume();

                            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                            const audioBuffer = await decodeAudioData(decode(audioData), outCtx, 24000, 1);

                            const source = outCtx.createBufferSource();
                            source.buffer = audioBuffer;
                            source.connect(outCtx.destination);
                            source.addEventListener('ended', () => { audioSourcesRef.current.delete(source); });
                            source.start(nextStartTimeRef.current);
                            nextStartTimeRef.current += audioBuffer.duration;
                            audioSourcesRef.current.add(source);
                        }

                         if (message.serverContent?.interrupted) {
                            audioSourcesRef.current.forEach(source => { try { source.stop(); } catch (e) {} });
                            audioSourcesRef.current.clear();
                            nextStartTimeRef.current = 0;
                        }

                        if (message.serverContent?.turnComplete) {
                             if (onTurnComplete) {
                                onTurnComplete(accumulatedTranscriptRef.current.userInput, accumulatedTranscriptRef.current.modelOutput);
                            }
                            accumulatedTranscriptRef.current = { userInput: '', modelOutput: '' };
                            setTranscript({ userInput: '', modelOutput: '' });
                        }
                    },
                    onerror: (e: ErrorEvent) => {
                        console.error('Live session error:', e);
                        stopSession();
                    },
                    onclose: () => { stopSession(); },
                },
            });

            const session = await sessionPromise;
            if (isStoppingRef.current) {
                session.close();
                return;
            }
            liveSessionRef.current = session;

        } catch (e: any) {
            console.error("Live start failed", e);
            stopSession();

            let errMsg = "Microphone or connection failed.";
            const msg = e.message || e.toString();

            if (msg.includes('No microphone found')) {
                errMsg = "No microphone detected. Please connect a microphone.";
            } else if (msg.includes('permission denied')) {
                errMsg = "Microphone access denied. Please allow permissions.";
            } else if (msg.includes('Media API not available')) {
                errMsg = "Voice is not supported in this browser context (HTTPS required).";
            } else {
                errMsg = "Live connection failed: " + msg;
            }

            setError(errMsg);
        }
    }, [isLive, stopSession, onTurnComplete]);

    // Helper for ScriptProcessor fallback
    const fallbackToScriptProcessor = (sessionPromise: Promise<LiveSession>) => {
        if (!inputAudioContextRef.current || !mediaStreamSourceRef.current) return;

        console.log("Using ScriptProcessorNode fallback for audio input.");
        scriptProcessorRef.current = inputAudioContextRef.current.createScriptProcessor(4096, 1, 1);
        scriptProcessorRef.current.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const pcmBlob = createBlob(inputData);
            sessionPromise.then((session) => session.sendRealtimeInput({ media: pcmBlob }));
        };
        mediaStreamSourceRef.current.connect(scriptProcessorRef.current);
        scriptProcessorRef.current.connect(inputAudioContextRef.current.destination);
    };

    useEffect(() => {
        return () => { if (isLive) stopSession(); };
    }, [stopSession]);

    return { isLive, transcript, startSession, stopSession, error };
};

import { useState, useRef, useCallback, useEffect } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { MODEL_CONFIGS, SCRIBE_SYSTEM_INSTRUCTION } from '../../constants';
import { ChatMode } from '../../types';
import { SoapNote } from './types';

// Type definition for the object expected by session.sendRealtimeInput
type LiveInputMedia = {
    data: string;
    mimeType: string;
};

const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
