export const useScribeSession = () => {
    const [isActive, setIsActive] = useState(false);
    const [soapNote, setSoapNote] = useState<SoapNote>({
        subjective: '',
        objective: '',
        assessment: '',
        plan: ''
    });
    const [transcript, setTranscript] = useState<string[]>([]);
    const [error, setError] = useState<string | null>(null);

    const liveSessionRef = useRef<any>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const mediaStreamSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
    const workletNodeRef = useRef<AudioWorkletNode | null>(null);
    const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
    const workletSupportedRef = useRef<boolean>(false);

    // Accumulator for the current turn to debounce updates
    const currentTurnRef = useRef<string>('');

    const stopSession = useCallback(async () => {
        try {
            if (liveSessionRef.current) {
                liveSessionRef.current.close();
                liveSessionRef.current = null;
            }
            workletNodeRef.current?.disconnect();
            scriptProcessorRef.current?.disconnect();
            mediaStreamSourceRef.current?.disconnect();

            workletNodeRef.current = null;
            scriptProcessorRef.current = null;

            if (audioContextRef.current && audioContextRef.current.state === 'running') {
                await audioContextRef.current.suspend();
            }
        } catch(e) {
            console.error("Scribe stop error", e);
        } finally {
            setIsActive(false);
        }
    }, []);

    const startSession = useCallback(async () => {
        if (isActive) return;
        setError(null);
        setTranscript([]); // Clear previous transcript
        currentTurnRef.current = '';

        try {
             // 1. Audio Setup
             if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 16000 });
            }
            if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();

            // Load Worklet (CSP Compliant via static file)
            try {
                await audioContextRef.current.audioWorklet.addModule('/workers/pcm-processor.js');
                workletSupportedRef.current = true;
            } catch (e) {
                 console.warn("Scribe Worklet module load failed, defaulting to ScriptProcessor fallback:", e);
                 workletSupportedRef.current = false;
            }

            const stream = await navigator.mediaDevices.getUserMedia({ 
                audio: { echoCancellation: true, noiseSuppression: true } 
            });

            setIsActive(true);

            // 2. Connect Gemini
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const sessionPromise = ai.live.connect({
                model: MODEL_CONFIGS[ChatMode.Scribe].model,
                config: {
                    ...MODEL_CONFIGS[ChatMode.Scribe].config,
                    systemInstruction: SCRIBE_SYSTEM_INSTRUCTION
                },
                callbacks: {
                    onopen: async () => {
                         if (!audioContextRef.current) return;
                         mediaStreamSourceRef.current = audioContextRef.current.createMediaStreamSource(stream);

                         const setupScriptProcessor = () => {
                             console.log("Using ScriptProcessorNode fallback for Scribe.");
                             scriptProcessorRef.current = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
                             scriptProcessorRef.current.onaudioprocess = (e) => {
                                 const inputData = e.inputBuffer.getChannelData(0);
                                 const pcmBlob = createBlob(inputData);
                                 sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
                             };
                             mediaStreamSourceRef.current!.connect(scriptProcessorRef.current);
                             scriptProcessorRef.current.connect(audioContextRef.current!.destination);
                         };

                         if (workletSupportedRef.current) {
                             try {
                                 workletNodeRef.current = new AudioWorkletNode(audioContextRef.current, 'pcm-processor');
                                 workletNodeRef.current.port.onmessage = (e) => {
                                     const inputData = e.data;
                                     const pcmBlob = createBlob(inputData);
                                     sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
                                 };
                                 mediaStreamSourceRef.current.connect(workletNodeRef.current);
                                 workletNodeRef.current.connect(audioContextRef.current.destination);
                             } catch (e) {
                                 console.error("Scribe Worklet creation failed:", e);
                                 setupScriptProcessor();
                             }
                         } else {
                             setupScriptProcessor();
                         }
                    },
                    onmessage: async (message: LiveServerMessage) => {
                        // Handle Input Transcription (User Speech)
                        if (message.serverContent?.inputTranscription) {
                            const text = message.serverContent.inputTranscription.text;
                            currentTurnRef.current += text;
                        }

                        // Commit turn to transcript array when turn is complete
                        if (message.serverContent?.turnComplete && currentTurnRef.current.trim()) {
                            setTranscript(prev => [...prev, currentTurnRef.current.trim()]);
                            currentTurnRef.current = '';
                        }

                        // Handle Tool Calls (SOAP Note Updates)
                        if (message.toolCall) {
                            for (const fc of message.toolCall.functionCalls) {
                                if (fc.name === 'updateSoapNote') {
                                    // Update State with partial or full updates
                                    const args = fc.args as any;
                                    setSoapNote(prev => ({
                                        subjective: args.subjective || prev.subjective,
                                        objective: args.objective || prev.objective,
                                        assessment: args.assessment || prev.assessment,
                                        plan: args.plan || prev.plan
                                    }));

                                    // Send Success Response
                                    sessionPromise.then(session => session.sendToolResponse({
                                        functionResponses: [{ id: fc.id, name: fc.name, response: { result: "Note updated" } }]
                                    }));
                                }
                            }
                        }
                    },
                    onerror: (e) => {
                        console.error("Scribe error", e);
                        setError("Scribe connection failed.");
                        stopSession();
                    },
                    onclose: () => stopSession()
                }
            });
            liveSessionRef.current = await sessionPromise;

        } catch (e: any) {
            console.error("Failed to start scribe", e);
            setError(e.message || "Could not start recording.");
            setIsActive(false);
        }
    }, [isActive, stopSession]);

    useEffect(() => {
        return () => { stopSession(); };
    }, [stopSession]);

    return { 
        isActive, 
        soapNote,
        transcript, 
        setSoapNote, // allow manual edits
        startSession, 
        stopSession, 
        error 
    };
};

const FDA_API_BASE = 'https://api.fda.gov/drug/label.json';

export interface DrugSafetyInfo {
    status: 'verified' | 'not_found' | 'service_error';
    found: boolean; // Deprecated but kept for compatibility, maps to status !== 'not_found'
    brandName?: string;
    genericName?: string;
    boxedWarning?: string[]; // The critical "Black Box" warning
    generalWarnings?: string[];
    source: 'openFDA' | 'Unknown';
}

// Simple in-memory cache to prevent redundant network calls during a session
const SAFETY_CACHE: Record<string, DrugSafetyInfo> = {};

/**
 * Queries openFDA for drug label information.
 * Focuses on 'boxed_warning' which is the highest safety alert level.
 */
export const fetchDrugSafetyInfo = async (drugName: string, signal?: AbortSignal): Promise<DrugSafetyInfo> => {
    // 1. Check Cache
    const cacheKey = drugName.toLowerCase().trim();
    if (SAFETY_CACHE[cacheKey]) {
        return SAFETY_CACHE[cacheKey];
    }

    try {
        // 2. Construct Query
        // We search both brand and generic names for best coverage
        const searchQuery = `openfda.brand_name:"${drugName}"+OR+openfda.generic_name:"${drugName}"`;
        const url = `${FDA_API_BASE}?search=${searchQuery}&limit=1`;

        const response = await fetch(url, { signal });

        if (response.status === 429 || response.status >= 500) {
            throw new Error("Service Unavailable");
        }

        if (!response.ok) {
            // 404 means drug not found in FDA database (or name mismatch)
            const result: DrugSafetyInfo = { status: 'not_found', found: false, source: 'openFDA' };
            SAFETY_CACHE[cacheKey] = result;
            return result;
        }

        const data = await response.json();
        const resultEntry = data.results?.[0];

        if (!resultEntry) {
            const result: DrugSafetyInfo = { status: 'not_found', found: false, source: 'openFDA' };
            SAFETY_CACHE[cacheKey] = result;
            return result;
        }

        // 3. Extract Critical Safety Data
        const info: DrugSafetyInfo = {
            status: 'verified',
            found: true,
            brandName: resultEntry.openfda?.brand_name?.[0],
            genericName: resultEntry.openfda?.generic_name?.[0],
            boxedWarning: resultEntry.boxed_warning, // This is the key field for safety
            generalWarnings: resultEntry.warnings ? resultEntry.warnings.slice(0, 1) : undefined, // Grab first paragraph of general warnings
            source: 'openFDA'
        };

        // 4. Cache and Return
        SAFETY_CACHE[cacheKey] = info;
        return info;

    } catch (error: any) {
        if (error.name === 'AbortError') {
            throw error; // Propagate abort
        }
        console.warn(`openFDA Fetch Error for ${drugName}:`, error);
        // Fail open - we don't want to block the UI, but we explicitly report the error
        return { status: 'service_error', found: false, source: 'Unknown' };
    }
};

import { fetchDrugSafetyInfo } from './openFdaService';
import { ParsedMedication, SafetyCheckResult } from './types';

// Fallback "Fast" limits for common OTC items if network fails or for double-checking
// We keep a small subset of the old list as a "Local Guardrail" for extreme outliers
const CRITICAL_LIMITS: Record<string, number> = {
    "acetaminophen": 4000,
    "paracetamol": 4000,
    "ibuprofen": 3200,
    "aspirin": 4000
};

/**
 * ASYNCHRONOUS EXTERNAL GUARDRAIL
 * Queries openFDA to check for "Boxed Warnings" (Black Box) and verifies dosage against local critical limits.
 */
export const verifyMedicationSafetyAsync = async (medications: ParsedMedication[], signal?: AbortSignal): Promise<SafetyCheckResult> => {
    const warnings: string[] = [];
    const verifiedItems: string[] = [];
    let serviceError = false;

    // Process all meds in parallel
    const promises = medications.map(async (med) => {
        if (signal?.aborted) return;

        const lowerName = med.drugName.toLowerCase();

        // 1. External Verification (openFDA)
        let fdaData;
        try {
            fdaData = await fetchDrugSafetyInfo(lowerName, signal);
        } catch (e: any) {
            if (e.name === 'AbortError') throw e;
            fdaData = { status: 'service_error' };
        }

        if (signal?.aborted) return;

        if (fdaData.status === 'service_error') {
            serviceError = true;
            warnings.push(
                `⚠️ **NETWORK ERROR**: Unable to verify ${med.drugName} against FDA database.`
            );
        } else if (fdaData.status === 'verified') {
            const displayName = fdaData.genericName || fdaData.brandName || med.drugName;

            // CHECK: Boxed Warning (The most critical safety check)
            if (fdaData.boxedWarning && fdaData.boxedWarning.length > 0) {
                // Truncate warning for UI clarity
                const shortWarn = fdaData.boxedWarning[0].substring(0, 150) + "...";
                warnings.push(
                    `🛑 **FDA BOXED WARNING** (${displayName}): ${shortWarn}`
                );
            } else {
                 verifiedItems.push(
                    `✅ Verified (${displayName}): No Boxed Warning found in FDA Label.`
                );
            }
        } else {
            // Not found in FDA
        }

        // 2. Local Critical Limit Check (Dosage Math)
        // We attempt to match simple names to our small critical list
        const limit = CRITICAL_LIMITS[lowerName];
        if (limit) {
            // Simple normalization
            let amountMg = med.amount;
            if (med.unit.toLowerCase().includes('g')) amountMg = med.amount * 1000;

            if (amountMg > limit) {
                warnings.push(
                    `⚠️ **DOSAGE LIMIT EXCEEDED**: ${med.drugName} ${med.amount}${med.unit} exceeds critical limit of ${limit}mg/day.`
                );
            }
        }
    });

    try {
        await Promise.all(promises);
    } catch (error: any) {
        if (error.name === 'AbortError') {
            // If aborted, we can return a safe default or re-throw
            // Typically re-throwing lets the caller know it was cancelled
            throw error; 
        }
    }

    return {
        isSafe: warnings.length === 0,
        warnings,
        verifiedItems,
        serviceError
    };
};

import React, { useState, useEffect, useRef } from 'react';
import type { ChatMessage } from '../../../types';
import { LinkIcon, DocumentTextIcon, ClipboardIcon, CheckIcon, AlertTriangleIcon, ShieldCheckIcon, BoltIcon } from '../../../components/icons';
import MessageContent from './MessageContent';
import { extractMedicationsFromText } from '../../safety/safetyExtractionService';
import { verifyMedicationSafetyAsync } from '../../safety/dosageVerifier';
import { SafetyCheckResult } from '../../safety/types';
import { blobStorage } from '../../../services/blobStorageService';

const isHighCredibilitySource = (uri: string) => {
    try {
        const url = new URL(uri);
        const domain = url.hostname.toLowerCase();
        return domain.endsWith('.gov') || 
               domain.endsWith('.org') || 
               domain.endsWith('.edu') || 
               domain.includes('mayoclinic') ||
               domain.includes('webmd') || 
               domain.includes('medscape') ||
               domain.includes('ncbi') ||
               domain.includes('pubmed');
    } catch {
        return false;
    }
};

