import { GoogleGenAI } from "@google/genai";
import { UploadedFile } from '../../types';
import { ENTITY_EXTRACTION_PROMPT } from '../../constants';
import { cleanJsonOutput, parseAndValidate } from '../../utils';
import { PatientEntityData } from '../patient-management/types';
import { EntityExtractionSchema } from '../chat/schemas';

const MODEL = 'gemini-3-flash-preview'; 

export const extractEntitiesFromUpload = async (file: UploadedFile, signal?: AbortSignal): Promise<Partial<PatientEntityData>> => {
    try {
        if (signal?.aborted) return {};

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const contents = [
            {
                role: 'user',
                parts: [
                    {
                        inlineData: {
                            mimeType: file.type,
                            data: file.base64
                        }
                    },
                    { text: ENTITY_EXTRACTION_PROMPT }
                ]
            }
        ];

        const response = await ai.models.generateContent({
            model: MODEL,
            contents: contents,
            config: {
                responseMimeType: 'application/json'
            }
        });

        if (signal?.aborted) return {};

        const text = response.text;
        if (!text) return {};

        // Validated parsing
        const parsed = parseAndValidate(text, EntityExtractionSchema);
        if (!parsed) return {};

        const result: Partial<PatientEntityData> = {};

        if (parsed.allergies && parsed.allergies.length > 0) {
            result.allergies = parsed.allergies;
        }

        if (parsed.codeStatus && parsed.codeStatus.trim()) {
            result.codeStatus = parsed.codeStatus.trim();
        }

        if (parsed.diagnosis && parsed.diagnosis.length > 0) {
            result.diagnosis = parsed.diagnosis;
        }

        return result;

    } catch (e) {
        // If it was just an abort, we can ignore warning
        if (signal?.aborted) return {};
        console.warn("Entity Extraction Failed:", e);
        return {};
    }
};

import React, { useCallback, useRef, useEffect } from 'react';
import { UploadedFile } from '../types';
import { extractEntitiesFromUpload } from '../features/clinical-analysis/entityExtractionService';
import { usePatientStore } from '../features/patient-management/usePatientStore';

export const useEntityExtractor = () => {
    const actions = usePatientStore(state => state.actions);
    const abortControllerRef = useRef<AbortController | null>(null);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            if (abortControllerRef.current) {
                abortControllerRef.current.abort();
            }
        };
    }, []);

    const triggerExtraction = useCallback(async (file: UploadedFile, patientId: string) => {
        // Abort any pending extraction
        if (abortControllerRef.current) {
            abortControllerRef.current.abort();
        }

        const controller = new AbortController();
        abortControllerRef.current = controller;

        // Run in background (fire and forget from UI perspective)
        extractEntitiesFromUpload(file, controller.signal).then(entities => {
            if (controller.signal.aborted) return;

            if (Object.keys(entities).length > 0) {
                actions.updatePatientEntities(patientId, entities);
            }
        }).catch(err => {
            // Ignore errors here, service logs them
        }).finally(() => {
            if (abortControllerRef.current === controller) {
                abortControllerRef.current = null;
            }
        });
    }, [actions]);

    return { triggerExtraction };
};

import React, { useState } from 'react';
import { ParsedMedication } from '../../safety/types';
import { PillIcon, CheckIcon, XCircleIcon, BoltIcon } from '../../../components/icons';

interface MedicationReviewCardProps {
    medications: ParsedMedication[];
    onConfirm: (meds: ParsedMedication[]) => void;
    onDiscard: () => void;
}

const MedicationReviewCard: React.FC<MedicationReviewCardProps> = ({ medications, onConfirm, onDiscard }) => {
    const [editedMeds, setEditedMeds] = useState<ParsedMedication[]>(medications);

    const handleChange = (index: number, field: keyof ParsedMedication, value: string | number) => {
        const newMeds = [...editedMeds];
        newMeds[index] = { ...newMeds[index], [field]: value };
        setEditedMeds(newMeds);
    };

    const handleRemove = (index: number) => {
        const newMeds = editedMeds.filter((_, i) => i !== index);
