import React, { useState, useCallback, useEffect, useRef } from 'react';
import { ChatMode as ChatModeEnum } from '../../types';
import Header from '../../components/Header';
import MessageList from '../chat/components/MessageList';
import InputBar from '../chat/components/InputBar';
import ImageViewer from '../../components/ImageViewer';
import SidebarRoster from '../patient-roster/SidebarRoster';
import HeadsUpDisplay from '../hud/HeadsUpDisplay';
import ScribeInterface from '../scribe/ScribeInterface';
import CDSSContainer from '../cdss/CDSSContainer';
import BioMetricBackground from './BioMetricBackground';
import { useLiveSession } from '../../hooks/useLiveSession';
import { useFileDragAndDrop } from '../../hooks/useFileDragAndDrop';
import { useChatOrchestrator } from '../chat/hooks/useChatOrchestrator';
import { DocumentTextIcon, ShieldCheckIcon, EyeIcon } from '../../components/icons';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useChatStore } from '../chat/stores/useChatStore';
import { useUIStore } from '../ui/UIContext';

// --- IDLE TIMER CONSTANTS ---
const PRIVACY_BLUR_MS = 2 * 60 * 1000; // 2 Minutes -> Blur
const AUTO_LOCK_MS = 15 * 60 * 1000;   // 15 Minutes -> Full Lock

const MainLayout: React.FC = () => {
    // --- STORES ---
    const activePatientId = usePatientStore(state => state.activePatientId);
    const activePatient = usePatientStore(state => state.patients[activePatientId]);
    const chatActions = useChatStore(state => state.actions);

    // Select messages from the specialized Chat Store
    const activeMessages = useChatStore(state => state.chats[activePatientId] || []);

    const { uiState, uiDispatch } = useUIStore();

    // --- UI State ---
    const { uploadedFile, setUploadedFile, isDragging, clearFile, dragHandlers } = useFileDragAndDrop();
    const { chatMode, isLoading } = uiState;

    // --- Local UI State ---
    const [userLocation, setUserLocation] = useState<{latitude: number, longitude: number} | undefined>(undefined);
    const [viewingImage, setViewingImage] = useState<{src: string, alt: string} | null>(null);
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);

    // Security State
    const [isLocked, setIsLocked] = useState(false);
    const [isBlurred, setIsBlurred] = useState(false);
    const lastActivityRef = useRef(Date.now());

    // --- IDLE LOCK LOGIC ---
    useEffect(() => {
        const resetTimer = () => {
            lastActivityRef.current = Date.now();
            setIsBlurred(prev => prev ? false : prev); // Optimistic unblur
        };

        const checkIdle = () => {
            const idleTime = Date.now() - lastActivityRef.current;

            if (idleTime > AUTO_LOCK_MS) {
                setIsLocked(true);
            } else if (idleTime > PRIVACY_BLUR_MS) {
                setIsBlurred(true);
            }
        };

        // Events to track activity
        window.addEventListener('mousemove', resetTimer);
        window.addEventListener('keydown', resetTimer);
        window.addEventListener('touchstart', resetTimer);
        window.addEventListener('scroll', resetTimer);

        // Check interval
        const intervalId = setInterval(checkIdle, 5000); // Check every 5s

        return () => {
            window.removeEventListener('mousemove', resetTimer);
            window.removeEventListener('keydown', resetTimer);
            window.removeEventListener('touchstart', resetTimer);
            window.removeEventListener('scroll', resetTimer);
            clearInterval(intervalId);
        };
    }, []);

    // Responsive Sidebar Check
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) setIsSidebarOpen(false);
            else setIsSidebarOpen(true);
        };
        handleResize(); // Init
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // --- Geolocation ---
    useEffect(() => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => setUserLocation({ latitude: position.coords.latitude, longitude: position.coords.longitude }),
                (err) => console.debug("Location access denied or failed:", err.message)
            );
        }
    }, []);

    // --- Live Session Integration ---
    const handleLiveTurnComplete = useCallback((userInput: string, modelOutput: string) => {
        if (userInput) chatActions.addMessage(activePatientId, { role: 'user', content: userInput });
        if (modelOutput) chatActions.addMessage(activePatientId, { role: 'model', content: modelOutput });
    }, [chatActions, activePatientId]);

    const { isLive, transcript, startSession, stopSession, error: liveError } = useLiveSession(handleLiveTurnComplete);

    useEffect(() => {
        if (liveError) {
            chatActions.addMessage(activePatientId, { role: 'model', content: `Error: ${liveError}` });
            uiDispatch({ type: 'SET_ERROR', payload: liveError });
        }
    }, [liveError, chatActions, activePatientId, uiDispatch]);

    // FIX: Removed conflicting useEffect that auto-switched mode based on isLive.
    // Instead, we strictly enforce that leaving Live mode stops the session.
    useEffect(() => {
        if (chatMode !== ChatModeEnum.Live && isLive) {
            stopSession();
        }
    }, [chatMode, isLive, stopSession]);

    // --- Chat Orchestrator ---
    const { handleSend, handleStop, handleClearChat, handleExportChat } = useChatOrchestrator({
        messages: activeMessages, 
        activePatientId: activePatientId,
        activePatient: activePatient, 
        chatMode: chatMode,
        uiDispatch: uiDispatch, 
        uploadedFile,
        setUploadedFile,
        isLive,
        stopSession,
        userLocation,
        clearFile
    });

    const handleViewImage = useCallback((src: string, alt: string) => {
        setViewingImage({ src, alt });
    }, []);

    // FIX: Explicitly set mode when starting live session
    const toggleLiveSession = useCallback(() => {
        if (isLive) {
            stopSession();
        } else {
            uiDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Live });
            startSession(activeMessages);
        }
    }, [isLive, stopSession, startSession, activeMessages, uiDispatch]);

    // --- LOCK SCREEN UI (Full Security) ---
    if (isLocked) {
        return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-950 text-white relative overflow-hidden">
                <div className="absolute inset-0 bg-grid-pattern opacity-10"></div>
                <div className="z-10 bg-slate-900 border border-slate-700 p-8 rounded-md shadow-2xl max-w-sm w-full text-center technical-border">
                    <ShieldCheckIcon className="w-12 h-12 text-blue-500 mx-auto mb-4 animate-pulse" />
                    <h2 className="text-xl font-display font-bold uppercase tracking-widest mb-2">Session Locked</h2>
                    <p className="text-sm text-slate-400 font-mono mb-6">Security Timeout (15m)</p>
                    <button 
                        onClick={() => {
                            lastActivityRef.current = Date.now();
                            setIsLocked(false);
                            setIsBlurred(false);
                        }}
                        className="w-full py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold uppercase tracking-widest rounded-sm transition-colors"
                    >
                        Resume Session
                    </button>
                </div>
            </div>
        );
    }

    if (!process.env.API_KEY) {
         return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-100 dark:bg-slate-900 text-slate-800 dark:text-slate-200 p-4">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-xl shadow-lg max-w-md text-center">
                    <div className="text-red-500 text-5xl mb-4">⚠️</div>
                    <h1 className="text-xl font-bold mb-2">API Key Missing</h1>
                    <p className="text-slate-600 dark:text-slate-400">Environment variable <code>API_KEY</code> is required.</p>
                </div>
            </div>
         );
    }

    return (
        <div 
            className="flex h-[100dvh] font-sans overflow-hidden relative text-slate-900 dark:text-slate-100"
            {...dragHandlers}
        >
            <BioMetricBackground />

            {/* CONTENT WRAPPER: Applied Blur Filter here */}
            <div className={`flex flex-1 w-full h-full relative transition-all duration-700 ${isBlurred ? 'blur-md opacity-60 grayscale scale-[0.99] pointer-events-none' : ''}`}>
                <SidebarRoster 
                    isOpen={isSidebarOpen} 
                    toggle={() => setIsSidebarOpen(!isSidebarOpen)} 
                />

                <div className="flex-1 flex flex-col min-w-0 relative z-10">
                    <Header
                        currentMode={chatMode}
                        onModeChange={(mode) => uiDispatch({ type: 'SET_CHAT_MODE', payload: mode })}
                        onClearChat={handleClearChat}
                        onExportChat={handleExportChat}
                        onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                    />

                    {activePatient && (
                        <HeadsUpDisplay patient={activePatient} />
                    )}

                    <CDSSContainer />

                    {chatMode === ChatModeEnum.Scribe ? (
                        <ScribeInterface />
                    ) : (
                        <>
                            <MessageList 
                                messages={activeMessages} 
                                isLoading={isLoading} 
                                isLive={isLive} 
                                liveTranscript={transcript} 
                                onViewImage={handleViewImage}
                            />

                            <InputBar
                                onSend={handleSend}
                                onClearFile={clearFile}
                                setUploadedFile={setUploadedFile}
                                uploadedFile={uploadedFile}
                                isLoading={isLoading}
                                currentMode={chatMode}
                                toggleLiveSession={toggleLiveSession}
                                isLiveSessionActive={isLive}
                                onStop={handleStop}
                            />
                        </>
                    )}
                </div>
            </div>

            {/* PRIVACY SHIELD OVERLAY (Visible only when blurred) */}
            <div className={`absolute inset-0 z-[60] flex items-center justify-center pointer-events-none transition-opacity duration-500 ${isBlurred ? 'opacity-100' : 'opacity-0'}`}>
                 <div className="bg-slate-900/90 text-white px-8 py-4 rounded-full font-mono text-sm uppercase tracking-widest shadow-2xl border border-white/10 flex items-center gap-3 animate-slide-up">
                    <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
                    <EyeIcon className="w-4 h-4 text-emerald-500" />
                    <span>Privacy Shield Active</span>
                 </div>
            </div>

            {isDragging && (
                <div className="absolute inset-0 z-50 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center m-4 rounded-xl animate-fade-in pointer-events-none border-2 border-blue-500/50 shadow-[0_0_50px_rgba(59,130,246,0.3)]">
                    <div className="flex flex-col items-center text-blue-400 animate-pulse">
                        <DocumentTextIcon className="w-20 h-20 mb-6" />
                        <h2 className="text-3xl font-display font-bold tracking-tight">DATA INGESTION PROTOCOL</h2>
                        <p className="font-mono text-sm mt-2 opacity-70 uppercase tracking-widest">Release to initialize scan</p>
                    </div>
                </div>
            )}

            {viewingImage && (
                <ImageViewer 
                    src={viewingImage.src} 
                    alt={viewingImage.alt} 
                    onClose={() => setViewingImage(null)} 
                />
            )}
        </div>
    );
};

export default MainLayout;

import React, { useState, useRef } from 'react';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useChatStore } from '../chat/stores/useChatStore';
import { useClinicalStore } from '../clinical-analysis/stores/useClinicalStore';
import PatientCard from './PatientCard';
import AddPatientDialog from './AddPatientDialog';
import { ChevronLeftIcon, UsersIcon, DownloadIcon, ClipboardIcon, PlusIcon } from '../../components/icons';
import { useToast } from '../../components/Toast';
import { PatientMetadata, FullPatientContext } from '../patient-management/types';

interface SidebarRosterProps {
    isOpen: boolean;
    toggle: () => void;
}

const SidebarRoster: React.FC<SidebarRosterProps> = ({ isOpen, toggle }) => {
    // Optimized Selectors: Split to prevent object identity churn
    const patients = usePatientStore(state => state.patients);
    const activePatientId = usePatientStore(state => state.activePatientId);
    const actions = usePatientStore(state => state.actions);

    // Access other store actions for CRUD sync
    const chatActions = useChatStore(state => state.actions);
    const clinicalActions = useClinicalStore(state => state.actions);

    const { showToast } = useToast();
    const [isDialogOpen, setIsDialogOpen] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const patientsList = (Object.values(patients) as PatientMetadata[]).sort((a, b) => b.lastActive - a.lastActive);

    const handleSwitch = (id: string) => {
        actions.switchPatient(id);
    };

    const handleDelete = (id: string, name: string) => {
        if (Object.keys(patients).length <= 1) {
            showToast("Cannot delete the only active patient context.", 'error');
            return;
        }

        if (confirm(`Are you sure you want to delete the context for "${name}"?\nThis action cannot be undone.`)) {
             actions.deletePatient(id);
             chatActions.deleteChat(id);
             clinicalActions.deletePatient(id);
             showToast(`Patient context deleted`, 'info');
        }
    };

    const handleCreate = (name: string) => {
        const newId = actions.createPatient(name);
        chatActions.initializeChat(newId);
        clinicalActions.initializePatient(newId);
        setIsDialogOpen(false);
        showToast(`Patient context '${name}' initialized`, 'success');
    };

    const handleExportData = () => {
        try {
            const chatState = useChatStore.getState().chats;
            const clinicalState = useClinicalStore.getState().data;
            const alertsState = useClinicalStore.getState().alerts;

            // Construct composite export object
            const exportData: Record<string, FullPatientContext> = {};
            Object.keys(patients).forEach(id => {
                exportData[id] = {
                    ...patients[id],
                    chatHistory: chatState[id] || [],
                    clinicalData: clinicalState[id] || { observations: [] },
                    activeAlerts: alertsState[id] || []
                };
            });

            const payload = { 
                version: '4.2', 
                patients: exportData, 
                activePatientId 
            };

            const dataStr = JSON.stringify(payload);
            const blob = new Blob([dataStr], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `medibrief-backup-${new Date().toISOString().split('T')[0]}.json`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            showToast('System backup downloaded successfully', 'success');
        } catch (e) {
            showToast('Failed to export system data', 'error');
        }
    };

    const handleImportClick = () => {
        fileInputRef.current?.click();
    };

    const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            try {
                const imported = JSON.parse(event.target?.result as string);

                if (imported && imported.patients) {
                    // Deconstruct and distribute to stores
                    const patientMeta: Record<string, PatientMetadata> = {};

                    Object.keys(imported.patients).forEach(id => {
                        const full = imported.patients[id] as FullPatientContext;

                        // 1. Meta Store
                        patientMeta[id] = {
                            id: full.id,
                            name: full.name,
                            status: full.status,
                            entities: full.entities,
                            documents: full.documents,
                            createdAt: full.createdAt,
                            lastActive: full.lastActive
                        };

                        // 2. Chat Store
                        useChatStore.setState(state => ({
                            chats: { ...state.chats, [id]: full.chatHistory || [] }
                        }));

                        // 3. Clinical Store
                        useClinicalStore.setState(state => ({
                            data: { ...state.data, [id]: full.clinicalData || { observations: [] } },
                            alerts: { ...state.alerts, [id]: full.activeAlerts || [] }
                        }));
                    });

                    actions.setAllPatients(patientMeta, imported.activePatientId || Object.keys(patientMeta)[0]);

                    showToast('System state restored successfully.', 'success');
                } else {
                    throw new Error("Invalid format");
                }
            } catch (error) {
                console.error(error);
                showToast('Invalid backup file format', 'error');
            }
        };
        reader.readAsText(file);
        e.target.value = ''; // Reset input
    };

    return (
        <>
            <aside 
                className={`
                    flex-shrink-0 bg-white/95 dark:bg-[#080b14]/95 backdrop-blur-xl border-r border-slate-200 dark:border-white/5 transition-all duration-300 ease-in-out relative z-40
                    ${isOpen ? 'w-80' : 'w-0 opacity-0 md:opacity-100 md:w-16'}
                `}
            >
                <button
                    onClick={toggle}
                    className={`
                        absolute -right-3 top-20 z-50 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full p-1.5 shadow-float text-slate-500 hover:text-blue-500 transition-colors
                        ${isOpen ? 'rotate-0' : 'rotate-180'}
                    `}
                    aria-label="Toggle Roster"
                >
                    <ChevronLeftIcon className="w-3 h-3" />
                </button>

                <div className={`flex flex-col h-full overflow-hidden ${!isOpen && 'hidden md:flex'}`}>

                    {/* Header */}
                    <div className="p-5 border-b border-slate-100 dark:border-white/5 flex items-center justify-between h-20">
                        {isOpen ? (
                            <div className="flex items-center gap-2 text-slate-800 dark:text-slate-200">
                                <div className="p-2 bg-blue-50 dark:bg-slate-800 rounded-lg text-blue-500">
                                    <UsersIcon className="w-5 h-5" />
                                </div>
                                <div>
                                    <span className="font-bold text-sm tracking-tight block">Patient Roster</span>
                                    <span className="text-[10px] text-slate-400 font-medium">ACTIVE CONTEXTS</span>
                                </div>
                            </div>
                        ) : (
                            <div className="w-full flex justify-center">
                                <UsersIcon className="w-5 h-5 text-slate-400" />
                            </div>
                        )}

                        {isOpen && (
                            <div className="text-[10px] font-bold text-slate-500 bg-slate-100 dark:bg-white/5 px-2 py-1 rounded-full">
                                {patientsList.length}
                            </div>
                        )}
                    </div>

                    {/* Patient List */}
                    <div className="flex-1 overflow-y-auto p-3 space-y-3 bg-slate-50/50 dark:bg-transparent">
                        {isOpen ? (
                            patientsList.map(patient => (
                                <PatientCard
                                    key={patient.id}
                                    patient={patient}
                                    isActive={patient.id === activePatientId}
                                    onClick={() => handleSwitch(patient.id)}
                                    onDelete={(e) => handleDelete(patient.id, patient.name)}
                                />
                            ))
                        ) : (
                            <div className="flex flex-col gap-3 items-center mt-2">
                                {patientsList.map(patient => (
                                    <button
                                        key={patient.id}
                                        onClick={() => handleSwitch(patient.id)}
                                        className={`w-10 h-10 rounded-xl flex items-center justify-center border transition-all relative group shadow-sm
                                            ${patient.id === activePatientId 
                                                ? 'bg-blue-600 border-blue-600 text-white shadow-blue-500/30' 
                                                : 'bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-400 hover:border-blue-400'
                                            }
                                        `}
                                        title={patient.name}
                                    >
                                        <span className="text-xs font-bold">
                                            {patient.name.substring(0, 2).toUpperCase()}
                                        </span>
                                        <div className={`absolute -top-1 -right-1 w-3 h-3 rounded-full border-2 border-white dark:border-slate-900 ${
                                            patient.status === 'Critical' ? 'bg-red-500' : 
                                            patient.status === 'Stable' ? 'bg-emerald-500' : 'bg-slate-400'
                                        }`}></div>
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Footer Actions */}
                    <div className="p-4 border-t border-slate-100 dark:border-white/5 bg-white dark:bg-black/20 space-y-3">
                        {isOpen ? (
                            <>
                                <button 
                                    onClick={() => setIsDialogOpen(true)}
                                    className="w-full flex items-center justify-center gap-2 bg-slate-900 hover:bg-slate-800 text-white px-4 py-3 rounded-lg text-xs font-bold uppercase tracking-wide transition-all shadow-lg shadow-slate-900/10 active:translate-y-0.5"
                                >
                                    <PlusIcon className="w-4 h-4" />
                                    <span>New Context</span>
                                </button>
                                <div className="flex gap-2">
                                    <button 
                                        onClick={handleExportData}
                                        className="flex-1 flex items-center justify-center gap-1.5 bg-white dark:bg-white/5 border border-slate-200 dark:border-white/10 hover:bg-slate-50 dark:hover:bg-white/10 text-slate-600 dark:text-slate-400 px-3 py-2 rounded-lg text-[10px] font-bold uppercase transition-colors"
                                        title="Backup Data"
                                    >
                                        <DownloadIcon className="w-3.5 h-3.5" />
                                        <span>Backup</span>
                                    </button>
                                    <button 
                                        onClick={handleImportClick}
                                        className="flex-1 flex items-center justify-center gap-1.5 bg-white dark:bg-white/5 border border-slate-200 dark:border-white/10 hover:bg-slate-50 dark:hover:bg-white/10 text-slate-600 dark:text-slate-400 px-3 py-2 rounded-lg text-[10px] font-bold uppercase transition-colors"
                                        title="Restore Data"
                                    >
                                        <ClipboardIcon className="w-3.5 h-3.5" />
                                        <span>Restore</span>
                                    </button>
                                </div>
                            </>
                        ) : (
                             <button 
                                onClick={() => setIsDialogOpen(true)}
                                className="w-full flex items-center justify-center p-3 text-slate-400 hover:text-blue-500 transition-colors"
                                title="Add Patient"
                            >
                                <PlusIcon className="w-6 h-6" />
                            </button>
                        )}
                        <input type="file" ref={fileInputRef} className="hidden" accept=".json" onChange={handleFileImport} />
                    </div>
                </div>
            </aside>

            {/* Mobile Overlay - Lighter/Clean */}
            {isOpen && (
                <div 
                    className="md:hidden fixed inset-0 z-30 bg-slate-900/20 backdrop-blur-sm transition-opacity"
                    onClick={toggle}
                ></div>
            )}

            <AddPatientDialog 
                isOpen={isDialogOpen} 
                onClose={() => setIsDialogOpen(false)} 
                onSubmit={handleCreate} 
            />
        </>
    );
};

