import React, { useState, useCallback, useEffect, useRef } from 'react';
import { ChatMode as ChatModeEnum, ChatMessage } from '../../types';
import Header from '../../components/Header';
import MessageList from '../chat/components/MessageList';
import InputBar from '../chat/components/InputBar';
import ImageViewer from '../../components/ImageViewer';
import SidebarRoster from '../patient-roster/SidebarRoster';
import HeadsUpDisplay from '../hud/HeadsUpDisplay';
import ScribeInterface from '../scribe/ScribeInterface';
import CDSSContainer from '../cdss/CDSSContainer';
import BioMetricBackground from './BioMetricBackground';
import { useLiveSession } from '../../hooks/useLiveSession';
import { useFileDragAndDrop } from '../../hooks/useFileDragAndDrop';
import { useChatOrchestrator } from '../chat/hooks/useChatOrchestrator';
import { DocumentTextIcon, ShieldCheckIcon, EyeIcon } from '../../components/icons';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useChatStore } from '../chat/stores/useChatStore';
import { useUIStore } from '../ui/UIContext';

// --- IDLE TIMER CONSTANTS ---
const PRIVACY_BLUR_MS = 2 * 60 * 1000; // 2 Minutes -> Blur
const AUTO_LOCK_MS = 15 * 60 * 1000;   // 15 Minutes -> Full Lock

// CONSTANT FOR STABLE REFERENCE
const EMPTY_MESSAGES: ChatMessage[] = [];

const MainLayout: React.FC = () => {
    // --- STORES ---
    const activePatientId = usePatientStore(state => state.activePatientId);
    const activePatient = usePatientStore(state => state.patients[activePatientId]);
    const chatActions = useChatStore(state => state.actions);

    // Select messages with STABLE reference fallback
    const activeMessages = useChatStore(state => state.chats[activePatientId] || EMPTY_MESSAGES);

    const { uiState, uiDispatch } = useUIStore();

    // --- UI State ---
    const { uploadedFile, setUploadedFile, isDragging, clearFile, dragHandlers } = useFileDragAndDrop();
    const { chatMode, isLoading } = uiState;

    // --- Local UI State ---
    const [userLocation, setUserLocation] = useState<{latitude: number, longitude: number} | undefined>(undefined);
    const [viewingImage, setViewingImage] = useState<{src: string, alt: string} | null>(null);
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);

    // Security State
    const [isLocked, setIsLocked] = useState(false);
    const [isBlurred, setIsBlurred] = useState(false);
    const lastActivityRef = useRef(Date.now());

    // --- IDLE LOCK LOGIC ---
    useEffect(() => {
        const resetTimer = () => {
            lastActivityRef.current = Date.now();
            setIsBlurred(prev => prev ? false : prev); // Optimistic unblur
        };

        const checkIdle = () => {
            const idleTime = Date.now() - lastActivityRef.current;

            if (idleTime > AUTO_LOCK_MS) {
                setIsLocked(true);
            } else if (idleTime > PRIVACY_BLUR_MS) {
                setIsBlurred(true);
            }
        };

        // Events to track activity
        window.addEventListener('mousemove', resetTimer);
        window.addEventListener('keydown', resetTimer);
        window.addEventListener('touchstart', resetTimer);
        window.addEventListener('scroll', resetTimer);

        // Check interval
        const intervalId = setInterval(checkIdle, 5000); // Check every 5s

        return () => {
            window.removeEventListener('mousemove', resetTimer);
            window.removeEventListener('keydown', resetTimer);
            window.removeEventListener('touchstart', resetTimer);
            window.removeEventListener('scroll', resetTimer);
            clearInterval(intervalId);
        };
    }, []);

    // Responsive Sidebar Check
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) setIsSidebarOpen(false);
            else setIsSidebarOpen(true);
        };
        handleResize(); // Init
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // --- Geolocation ---
    useEffect(() => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => setUserLocation({ latitude: position.coords.latitude, longitude: position.coords.longitude }),
                (err) => console.debug("Location access denied or failed:", err.message)
            );
        }
    }, []);

    // --- Live Session Integration ---
    const handleLiveTurnComplete = useCallback((userInput: string, modelOutput: string) => {
        if (userInput) chatActions.addMessage(activePatientId, { role: 'user', content: userInput });
        if (modelOutput) chatActions.addMessage(activePatientId, { role: 'model', content: modelOutput });
    }, [chatActions, activePatientId]);

    const { isLive, transcript, startSession, stopSession, error: liveError } = useLiveSession(handleLiveTurnComplete);

    useEffect(() => {
        if (liveError) {
            chatActions.addMessage(activePatientId, { role: 'model', content: `Error: ${liveError}` });
            uiDispatch({ type: 'SET_ERROR', payload: liveError });
        }
    }, [liveError, chatActions, activePatientId, uiDispatch]);

    // FIX: Removed conflicting useEffect that auto-switched mode based on isLive.
    // Instead, we strictly enforce that leaving Live mode stops the session.
    useEffect(() => {
        if (chatMode !== ChatModeEnum.Live && isLive) {
            stopSession();
        }
    }, [chatMode, isLive, stopSession]);

    // --- Chat Orchestrator ---
    const { handleSend, handleStop, handleClearChat, handleExportChat } = useChatOrchestrator({
        messages: activeMessages, 
        activePatientId: activePatientId,
        // Fallback for robust safety if store is hydrating
        activePatient: activePatient || { id: activePatientId, name: 'Loading...', status: 'New Admission', entities: { allergies: [], codeStatus: 'Full Code', diagnosis: [] }, documents: [], createdAt: 0, lastActive: 0 }, 
        chatMode: chatMode,
        uiDispatch: uiDispatch, 
        uploadedFile,
        setUploadedFile,
        isLive,
        stopSession,
        userLocation,
        clearFile
    });

    const handleViewImage = useCallback((src: string, alt: string) => {
        setViewingImage({ src, alt });
    }, []);

    // FIX: Explicitly set mode when starting live session
    const toggleLiveSession = useCallback(() => {
        if (isLive) {
            stopSession();
        } else {
            uiDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Live });
            startSession(activeMessages);
        }
    }, [isLive, stopSession, startSession, activeMessages, uiDispatch]);

    // --- LOCK SCREEN UI (Full Security) ---
    if (isLocked) {
        return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-950 text-white relative overflow-hidden">
                <div className="absolute inset-0 bg-grid-pattern opacity-10"></div>
                <div className="z-10 bg-slate-900 border border-slate-700 p-8 rounded-md shadow-2xl max-w-sm w-full text-center technical-border">
                    <ShieldCheckIcon className="w-12 h-12 text-blue-500 mx-auto mb-4 animate-pulse" />
                    <h2 className="text-xl font-display font-bold uppercase tracking-widest mb-2">Session Locked</h2>
                    <p className="text-sm text-slate-400 font-mono mb-6">Security Timeout (15m)</p>
                    <button 
                        onClick={() => {
                            lastActivityRef.current = Date.now();
                            setIsLocked(false);
                            setIsBlurred(false);
                        }}
                        className="w-full py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold uppercase tracking-widest rounded-sm transition-colors"
                    >
                        Resume Session
                    </button>
                </div>
            </div>
        );
    }

    if (!process.env.API_KEY) {
         return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-100 dark:bg-slate-900 text-slate-800 dark:text-slate-200 p-4">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-xl shadow-lg max-w-md text-center">
                    <div className="text-red-500 text-5xl mb-4">⚠️</div>
                    <h1 className="text-xl font-bold mb-2">API Key Missing</h1>
                    <p className="text-slate-600 dark:text-slate-400">Environment variable <code>API_KEY</code> is required.</p>
                </div>
            </div>
         );
    }

    return (
        <div 
            className="flex h-[100dvh] font-sans overflow-hidden relative text-slate-900 dark:text-slate-100"
            {...dragHandlers}
        >
            <BioMetricBackground />

            {/* CONTENT WRAPPER: Applied Blur Filter here */}
            <div className={`flex flex-1 w-full h-full relative transition-all duration-700 ${isBlurred ? 'blur-md opacity-60 grayscale scale-[0.99] pointer-events-none' : ''}`}>
                <SidebarRoster 
                    isOpen={isSidebarOpen} 
                    toggle={() => setIsSidebarOpen(!isSidebarOpen)} 
                />

                <div className="flex-1 flex flex-col min-w-0 relative z-10">
                    <Header
                        currentMode={chatMode}
                        onModeChange={(mode) => uiDispatch({ type: 'SET_CHAT_MODE', payload: mode })}
                        onClearChat={handleClearChat}
                        onExportChat={handleExportChat}
                        onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                    />

                    {activePatient && (
                        <HeadsUpDisplay patient={activePatient} />
                    )}

                    <CDSSContainer />

                    {chatMode === ChatModeEnum.Scribe ? (
                        <ScribeInterface />
                    ) : (
                        <>
                            <MessageList 
                                messages={activeMessages} 
                                isLoading={isLoading} 
                                isLive={isLive} 
                                liveTranscript={transcript} 
                                onViewImage={handleViewImage}
                            />

                            <InputBar
                                onSend={handleSend}
                                onClearFile={clearFile}
                                setUploadedFile={setUploadedFile}
                                uploadedFile={uploadedFile}
                                isLoading={isLoading}
                                currentMode={chatMode}
                                toggleLiveSession={toggleLiveSession}
                                isLiveSessionActive={isLive}
                                onStop={handleStop}
                            />
                        </>
                    )}
                </div>
            </div>

            {/* PRIVACY SHIELD OVERLAY (Visible only when blurred) */}
            <div className={`absolute inset-0 z-[60] flex items-center justify-center pointer-events-none transition-opacity duration-500 ${isBlurred ? 'opacity-100' : 'opacity-0'}`}>
                 <div className="bg-slate-900/90 text-white px-8 py-4 rounded-full font-mono text-sm uppercase tracking-widest shadow-2xl border border-white/10 flex items-center gap-3 animate-slide-up">
                    <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
                    <EyeIcon className="w-4 h-4 text-emerald-500" />
                    <span>Privacy Shield Active</span>
                 </div>
            </div>

            {isDragging && (
                <div className="absolute inset-0 z-50 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center m-4 rounded-xl animate-fade-in pointer-events-none border-2 border-blue-500/50 shadow-[0_0_50px_rgba(59,130,246,0.3)]">
                    <div className="flex flex-col items-center text-blue-400 animate-pulse">
                        <DocumentTextIcon className="w-20 h-20 mb-6" />
                        <h2 className="text-3xl font-display font-bold tracking-tight">DATA INGESTION PROTOCOL</h2>
                        <p className="font-mono text-sm mt-2 opacity-70 uppercase tracking-widest">Release to initialize scan</p>
                    </div>
                </div>
            )}

            {viewingImage && (
                <ImageViewer 
                    src={viewingImage.src} 
                    alt={viewingImage.alt} 
                    onClose={() => setViewingImage(null)} 
                />
            )}
        </div>
    );
};

export default MainLayout;

import React, { useState, useCallback, useMemo } from 'react';
import { v4 as uuidv4 } from 'uuid';
import type { UploadedFile } from '../types';
import { blobStorage } from '../services/blobStorageService';

export const useFileDragAndDrop = () => {
    const [uploadedFile, setUploadedFile] = useState<UploadedFile | null>(null);
    const [isDragging, setIsDragging] = useState(false);

    const handleDragOver = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        if ('ontouchstart' in window || navigator.maxTouchPoints > 0) return;
        if (!e.dataTransfer.types.includes('Files')) return;
        if (!isDragging) setIsDragging(true);
    }, [isDragging]);

    const handleDragLeave = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        if (e.currentTarget.contains(e.relatedTarget as Node)) return;
        setIsDragging(false);
    }, []);

    const processFile = useCallback(async (file: File) => {
        if (file.size > 10 * 1024 * 1024) { 
            alert("File is too large. Please select a file smaller than 10MB.");
            return;
        }
        const isSupported = file.type.startsWith('image/') || file.type === 'application/pdf' || file.type === 'text/plain' || file.name.endsWith('.md') || file.name.endsWith('.txt');
        if (!isSupported) {
             alert("Unsupported file type. Please upload Images, PDFs, or Text files.");
             return;
        }

        const reader = new FileReader();
        reader.onloadend = async () => {
            const base64 = (reader.result as string).split(',')[1];
            const storageId = uuidv4();

            // Persist to IndexedDB immediately to prevent memory issues
            try {
                await blobStorage.saveFile(storageId, base64, file.type);
            } catch (e) {
                console.error("Failed to save to IDB", e);
            }

            const uploadPayload: UploadedFile = { 
                file, 
                base64, // Keep base64 active for the *immediate* API call
                type: file.type,
                storageId 
            };

            if (file.type.startsWith('image/')) {
                uploadPayload.url = URL.createObjectURL(file);
            }
            setUploadedFile(uploadPayload);
        };
        reader.readAsDataURL(file);
    }, []);

    const handleDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const file = e.dataTransfer.files?.[0];
        if (file) processFile(file);
    }, [processFile]);

    const clearFile = useCallback(() => {
        setUploadedFile(null);
    }, []);

    const dragHandlers = useMemo(() => ({
        onDragOver: handleDragOver,
        onDragLeave: handleDragLeave,
        onDrop: handleDrop
    }), [handleDragOver, handleDragLeave, handleDrop]);

    return {
        uploadedFile,
        setUploadedFile, // Updated to potentially handle manual sets if needed
        processFile, // Exposed for input[type=file]
        isDragging,
        clearFile,
        dragHandlers
    };
};

import { useState, useRef, useCallback, useEffect, useMemo } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from "@google/genai";
import { MODEL_CONFIGS, SYSTEM_INSTRUCTION } from '../constants';
import { ChatMode, ChatMessage } from '../types';

declare global {
  interface Window {
    webkitAudioContext: typeof AudioContext;
  }
}

// Type definition for the object expected by session.sendRealtimeInput
type LiveInputMedia = {
    data: string;
    mimeType: string;
};

const encode = (bytes: Uint8Array) => {
  let binary = '';
  const len = bytes.byteLength;
  for (let i = 0; i < len; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

const decode = (base64: string) => {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const createBlob = (data: Float32Array): LiveInputMedia => {
  const l = data.length;
  const int16 = new Int16Array(l);
  for (let i = 0; i < l; i++) {
    const clamped = Math.max(-1, Math.min(1, data[i]));
    int16[i] = clamped < 0 ? clamped * 0x8000 : clamped * 0x7FFF;
  }
  return {
    data: encode(new Uint8Array(int16.buffer)),
    mimeType: 'audio/pcm;rate=16000',
  };
}

type LiveSession = Awaited<ReturnType<InstanceType<typeof GoogleGenAI>['live']['connect']>>;

export interface UseLiveSessionReturn {
    isLive: boolean;
    transcript: { userInput: string; modelOutput: string };
    startSession: (history?: ChatMessage[]) => Promise<void>;
    stopSession: () => Promise<void>;
    error: string | null;
}

export const useLiveSession = (onTurnComplete?: (userInput: string, modelOutput: string) => void): UseLiveSessionReturn => {
    const [isLive, setIsLive] = useState(false);
    const [transcript, setTranscript] = useState({ userInput: '', modelOutput: '' });
    const [error, setError] = useState<string | null>(null);

    const accumulatedTranscriptRef = useRef({ userInput: '', modelOutput: '' });
    const liveSessionRef = useRef<LiveSession | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const audioSourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
    const nextStartTimeRef = useRef<number>(0);
    const mediaStreamSourceRef = useRef<MediaStreamAudioSourceNode | null>(null);

    // Processors
    const workletNodeRef = useRef<AudioWorkletNode | null>(null);
    const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
    const workletSupportedRef = useRef<boolean>(false);

    const isStoppingRef = useRef(false);

    const stopSession = useCallback(async () => {
        if (isStoppingRef.current) return;
        isStoppingRef.current = true;

        try {
            // 1. Close the session socket first
            if (liveSessionRef.current) {
                liveSessionRef.current.close();
                liveSessionRef.current = null;
            }

            // 2. Disconnect audio nodes
            workletNodeRef.current?.disconnect();
            scriptProcessorRef.current?.disconnect();
            mediaStreamSourceRef.current?.disconnect();

            workletNodeRef.current = null;
            scriptProcessorRef.current = null;
            mediaStreamSourceRef.current = null;

            // 3. Stop all playing audio
            audioSourcesRef.current.forEach(source => {
                try { source.stop(); } catch(e) {}
            });
            audioSourcesRef.current.clear();

            // 4. Suspend AudioContexts cleanly
            if (inputAudioContextRef.current && inputAudioContextRef.current.state === 'running') {
                try { await inputAudioContextRef.current.suspend(); } catch(e) { console.warn("Input suspend failed", e); }
            }
            if (outputAudioContextRef.current && outputAudioContextRef.current.state === 'running') {
                try { await outputAudioContextRef.current.suspend(); } catch(e) { console.warn("Output suspend failed", e); }
            }

            nextStartTimeRef.current = 0;

            // 5. Finalize transcript
            if ((accumulatedTranscriptRef.current.userInput || accumulatedTranscriptRef.current.modelOutput) && onTurnComplete) {
                onTurnComplete(accumulatedTranscriptRef.current.userInput, accumulatedTranscriptRef.current.modelOutput);
            }

            accumulatedTranscriptRef.current = { userInput: '', modelOutput: '' };
            setTranscript({ userInput: '', modelOutput: '' });

        } catch (e) {
            console.error("Error during session stop:", e);
        } finally {
            setIsLive(false);
            isStoppingRef.current = false;
        }
    }, [onTurnComplete]);

    const startSession = useCallback(async (history: ChatMessage[] = []) => {
        if (isLive || isStoppingRef.current) return;

        setError(null);
        accumulatedTranscriptRef.current = { userInput: '', modelOutput: '' };

        try {
            // SAFETY CHECK: Check if mediaDevices API exists (it doesn't on insecure HTTP)
            if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
                throw new Error("Media API not available. Secure context (HTTPS) required.");
            }

            // 1. Initialize Audio Contexts (Singleton Pattern)
            if (!inputAudioContextRef.current || inputAudioContextRef.current.state === 'closed') {
                inputAudioContextRef.current = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 16000 });
            }
            if (!outputAudioContextRef.current || outputAudioContextRef.current.state === 'closed') {
                outputAudioContextRef.current = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 24000 });
            }

            // Resume if suspended
            if (inputAudioContextRef.current.state === 'suspended') await inputAudioContextRef.current.resume();
            if (outputAudioContextRef.current.state === 'suspended') await outputAudioContextRef.current.resume();

            // 2. Load AudioWorklet Module (CSP Compliant via static file)
            try {
                await inputAudioContextRef.current.audioWorklet.addModule('/workers/pcm-processor.js');
                workletSupportedRef.current = true;
            } catch (e) {
                console.warn("AudioWorklet module load failed, defaulting to ScriptProcessor fallback:", e);
                workletSupportedRef.current = false;
            }

            // 3. Get User Media
            let stream: MediaStream;
            try {
                stream = await navigator.mediaDevices.getUserMedia({ 
                    audio: {
                        echoCancellation: true,
                        noiseSuppression: true,
                        autoGainControl: true,
                    } 
                });
            } catch (mediaError: any) {
                if (mediaError.name === 'NotFoundError' || mediaError.name === 'DevicesNotFoundError') {
                    throw new Error("No microphone found on this device.");
                }
                if (mediaError.name === 'NotAllowedError' || mediaError.name === 'PermissionDeniedError') {
                    throw new Error("Microphone permission denied by user.");
                }
                throw mediaError;
            }

            setIsLive(true);

            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            // 4. Build Context String
            let contextString = "";
            if (history.length > 0) {
                const recentHistory = history.slice(-6).filter(m => m.content).map(m => {
                    const content = m.content.length > 200 ? m.content.substring(0, 200) + "..." : m.content;
                    return `${m.role.toUpperCase()}: ${content}`;
                }).join("\n");
                contextString = `\n\n[CONTEXT: ${recentHistory}]`;
            }

            // 5. Connect to Live API
            const sessionPromise = ai.live.connect({
                model: MODEL_CONFIGS[ChatMode.Live].model,
                config: {
                    ...MODEL_CONFIGS[ChatMode.Live].config,
                    systemInstruction: SYSTEM_INSTRUCTION + contextString
                },
                callbacks: {
                    onopen: async () => {
                        if (!inputAudioContextRef.current) return;
                        mediaStreamSourceRef.current = inputAudioContextRef.current.createMediaStreamSource(stream);

                        if (workletSupportedRef.current) {
                            // PRIMARY: AudioWorklet
                            try {
                                workletNodeRef.current = new AudioWorkletNode(inputAudioContextRef.current, 'pcm-processor');
                                workletNodeRef.current.port.onmessage = (event) => {
                                    const inputData = event.data;
                                    const pcmBlob = createBlob(inputData);
                                    sessionPromise.then((session) => session.sendRealtimeInput({ media: pcmBlob }));
                                };
                                mediaStreamSourceRef.current.connect(workletNodeRef.current);
                                workletNodeRef.current.connect(inputAudioContextRef.current.destination);
                            } catch (e) {
                                console.error("Worklet creation failed:", e);
                                workletSupportedRef.current = false; 
                                fallbackToScriptProcessor(sessionPromise);
                            }
                        } else {
                            // FALLBACK: ScriptProcessor
                            fallbackToScriptProcessor(sessionPromise);
                        }
                    },
                    onmessage: async (message: LiveServerMessage) => {
                        if (message.serverContent?.inputTranscription) {
                            accumulatedTranscriptRef.current.userInput += message.serverContent.inputTranscription.text;
                            setTranscript(prev => ({ ...prev, userInput: accumulatedTranscriptRef.current.userInput }));
                        }
                        if (message.serverContent?.outputTranscription) {
                            accumulatedTranscriptRef.current.modelOutput += message.serverContent.outputTranscription.text;
                            setTranscript(prev => ({ ...prev, modelOutput: accumulatedTranscriptRef.current.modelOutput }));
                        }

                        if (message.toolCall) {
                             for (const fc of message.toolCall.functionCalls) {
                                const result = { result: "Success" };
                                sessionPromise.then((session) => {
                                    if (liveSessionRef.current) {
                                        session.sendToolResponse({
                                            functionResponses: [{ id: fc.id, name: fc.name, response: result }]
                                        });
                                    }
                                });
                            }
                        }

                        const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData && outputAudioContextRef.current) {
                            const outCtx = outputAudioContextRef.current;
                            if (outCtx.state === 'suspended') await outCtx.resume();

                            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
                            const audioBuffer = await decodeAudioData(decode(audioData), outCtx, 24000, 1);

                            const source = outCtx.createBufferSource();
                            source.buffer = audioBuffer;
                            source.connect(outCtx.destination);
                            source.addEventListener('ended', () => { audioSourcesRef.current.delete(source); });
                            source.start(nextStartTimeRef.current);
                            nextStartTimeRef.current += audioBuffer.duration;
                            audioSourcesRef.current.add(source);
                        }

                         if (message.serverContent?.interrupted) {
                            audioSourcesRef.current.forEach(source => { try { source.stop(); } catch (e) {} });
                            audioSourcesRef.current.clear();
                            nextStartTimeRef.current = 0;
                        }

                        if (message.serverContent?.turnComplete) {
                             if (onTurnComplete) {
                                onTurnComplete(accumulatedTranscriptRef.current.userInput, accumulatedTranscriptRef.current.modelOutput);
                            }
                            accumulatedTranscriptRef.current = { userInput: '', modelOutput: '' };
                            setTranscript({ userInput: '', modelOutput: '' });
                        }
                    },
                    onerror: (e: ErrorEvent) => {
                        console.error('Live session error:', e);
                        stopSession();
                    },
                    onclose: () => { stopSession(); },
                },
            });

            const session = await sessionPromise;
            if (isStoppingRef.current) {
                session.close();
                return;
            }
            liveSessionRef.current = session;

        } catch (e: any) {
            console.error("Live start failed", e);
            stopSession();

            let errMsg = "Microphone or connection failed.";
            const msg = e.message || e.toString();

            if (msg.includes('No microphone found')) {
                errMsg = "No microphone detected. Please connect a microphone.";
            } else if (msg.includes('permission denied')) {
                errMsg = "Microphone access denied. Please allow permissions.";
            } else if (msg.includes('Media API not available')) {
                errMsg = "Voice is not supported in this browser context (HTTPS required).";
            } else {
                errMsg = "Live connection failed: " + msg;
            }

            setError(errMsg);
        }
    }, [isLive, stopSession, onTurnComplete]);

    // Helper for ScriptProcessor fallback
    const fallbackToScriptProcessor = (sessionPromise: Promise<LiveSession>) => {
        if (!inputAudioContextRef.current || !mediaStreamSourceRef.current) return;

        console.log("Using ScriptProcessorNode fallback for audio input.");
        scriptProcessorRef.current = inputAudioContextRef.current.createScriptProcessor(4096, 1, 1);
        scriptProcessorRef.current.onaudioprocess = (e) => {
            const inputData = e.inputBuffer.getChannelData(0);
            const pcmBlob = createBlob(inputData);
            sessionPromise.then((session) => session.sendRealtimeInput({ media: pcmBlob }));
        };
        mediaStreamSourceRef.current.connect(scriptProcessorRef.current);
        scriptProcessorRef.current.connect(inputAudioContextRef.current.destination);
    };

    useEffect(() => {
        return () => { if (isLive) stopSession(); };
    }, [stopSession]);

    return useMemo(() => ({ 
        isLive, transcript, startSession, stopSession, error 
    }), [isLive, transcript, startSession, stopSession, error]);
};
